// 1. System Call: Requesting process services (User -> Kernel Mode)
pid_t pid = fork();
if (pid == 0) {
    execlp("echo", "echo", "Child", NULL);
} else if (pid > 0) {
    waitpid(pid, NULL, 0);
}

// 2. ECF: Signal Handling (Software Interrupt/Async Event)
void sig_handler(int s) { 
    // Kernel transfers control flow to user-defined handler
}
struct sigaction sa = { .sa_handler = sig_handler };
sigaction(SIGINT, &sa, NULL);

// 3. Syscall Mechanism (Low-level invocation)
#define SYS_exit 60
long ret_val = syscall(SYS_exit, 0);
// Architecture specific instruction (e.g., 'syscall' on x86-64)
// causes trap/exception to kernel entry point
// ECF initiated by user code deliberately
char* p = NULL; *p = 'A'; // SIGSEGV (Hardware Exception ECF)
